import { criteria } from './data.js';
import { S,esc,icon,link,button,badge,photo,brand,header,footer,banner,tabs,field,select,heading,empty,workspace,fileLink,table,row,cardTitle,date,name,publicPage } from './ui.js';
export const currentProject=()=>S.projects.find(p=>p.id===S.selectedProject)||S.projects[0];
const steps=(project=false)=>`<div class="progress-steps ${project?'status-steps':''}">${(project?['Черновик','На проверке','Допущена','На экспертизе','Оценена']:['Регистрация','Тестовые задания','Исследовательский проект','Защита проекта']).map((t,i)=>`<div class="progress-step ${i===0?'done':''}"><span>${i===0?'✓':'0'+(i+1)}</span><strong>${t}</strong><small>${i===0?'Завершено':i===1?'В процессе':'Не начато'}</small><small>${i===0?'12 февр. 2025':''}</small></div>`).join('')}</div>`;
const fileCards=p=>(p?.files?.length?p.files.map(f=>`<div class="file-card">${icon(f.kind==='video'?'video':'file')}<div><strong>${esc(f.name)}</strong><small>${(f.size/1048576).toFixed(2)} МБ · ${date(f.date)}</small></div><a href="/api/files/${f.id}" class="text-link" aria-label="Скачать ${esc(f.name)}">${icon('download')}</a></div>`).join(''):empty('Файлы ещё не загружены'));
const upload=(label,key,p,required=false)=>`<div class="upload-zone">${icon(key==='video'?'video':'file')}<div><strong>${label}${required?' *':''}</strong><small>${key==='research'?'PDF, DOCX':key==='video'?'MP4':'PDF, PPTX'} · до ${(S.deployment.maxUploadBytes??(key==='research'?20e6:50e6))/1e6} МБ</small><div class="file-name" data-file-name="${key}">${esc(p?.files?.find(f=>f.kind===key)?.name||'')}</div></div><label class="btn sm">Загрузить<input type="file" data-upload="${key}" accept="${key==='research'?'.pdf,.docx':key==='video'?'.mp4':'.pdf,.pptx'}"></label></div>`;
export const accountPages={
 dashboard:()=>publicPage('dashboard',`<div class="dashboard-content">${banner(`Добро пожаловать,<br>${esc(name().split(' ')[1]||name().split(' ')[0])}!`,'Большое путешествие начинается с любопытства.<br>Продолжай свой путь в Арктике.',{tall:true,landscape:false,crumb:false,eyebrow:'Личный кабинет участника'})}<div class="container"><div class="floating-card"><div class="section-heading"><h3>Твой прогресс в конкурсе</h3>${link('test-intro','ПРОЙТИ ТЕСТ →','btn mint')}</div>${steps()}</div><div class="columns"><div class="card">${cardTitle('Мой проект',badge(currentProject()?.status||'Черновик'),'mail')}<p>${esc(currentProject()?.name||'Начни своё первое исследование Арктики.')}</p>${link(currentProject()?'project':'submit','ПРОДОЛЖИТЬ РАБОТУ →','btn sm')}</div><div class="card">${cardTitle('Уведомления',button('Все →','notifications','sm'),'bell')}<ul class="timeline"><li>Доступны тестовые задания<small>12 фев.</small></li><li>Ваш руководитель подтвердил сотрудничество<small>10 фев.</small></li><li>Новые материалы в библиотеке<small>8 фев.</small></li></ul></div><div class="card">${cardTitle('Ближайшие шаги','','file')}<ul class="timeline"><li>${link('test-intro','Пройди тестовые задания →')}</li><li>${link('submit','Доработай черновик проекта →')}</li><li>${link('documents','Изучи методические материалы →')}</li><li>${link('explore','Подготовь план исследования →')}</li></ul></div></div></div></div>`),
 profile:()=>{const p=S.user.profile,c=[...S.consents].sort((a,b)=>new Date(b.date)-new Date(a.date))[0];return workspace('profile','',heading('Мой профиль','Личные данные и документы участника. Проверь актуальность информации.')+`<div class="card">${cardTitle('Основная информация',button(icon('edit')+' Изменить','edit-profile','sm'),'mail')}<div class="profile-row">${photo('portrait','Фото участника','profile-avatar')}<dl class="data-list">${[['ФИО',p.name],['Дата рождения',p.birth?date(p.birth):'Укажите дату'],['Класс',p.grade+' класс'],['Школа',p.school],['Регион',p.region]].map(([t,v])=>`<dt>${t}</dt><dd>${esc(v||'Не указано')}</dd>`).join('')}</dl></div></div><div class="columns" style="margin-top:20px"><div class="card">${cardTitle('Контакты и законный представитель',button('Изменить','edit-profile','sm'),'users')}<dl class="data-list">${[['ФИО родителя/опекуна',p.parent],['Телефон',p.phone],['Email',p.parentEmail]].map(([t,v])=>`<dt>${t}</dt><dd>${esc(v||'Не указано')}</dd>`).join('')}</dl><div class="notice" style="margin-top:22px">${icon('lock')}Контакты используются только для организационных уведомлений по конкурсу.</div></div><div class="card">${cardTitle('Согласие законного представителя','','file')}<p>Загрузите подписанное согласие на обработку персональных данных.</p>${c?`<div class="file-card">${icon('file')}<div><strong>${esc(c.name||'Согласие при регистрации')}</strong><small>${date(c.date)}</small>${badge(c.status)}</div></div>`:empty('Согласие не загружено')}<label class="btn sm wide">${icon('upload')} ЗАГРУЗИТЬ ДРУГОЙ ДОКУМЕНТ<input type="file" data-upload="consent" accept=".pdf" hidden></label></div></div>`);},
 mentor:()=>workspace('mentor','',heading('Мой руководитель','Пригласи учителя-наставника, который будет сопровождать твою работу над проектом.')+`<div class="spaced"><div class="card invite-card">${cardTitle('Пригласить руководителя','','user')}<form class="invite-form" data-form="mentor"><input class="control" name="email" type="email" required placeholder="Введите email учителя" aria-label="Email учителя"><button class="btn primary sm">ОТПРАВИТЬ ПРИГЛАШЕНИЕ →</button><p class="form-error" role="alert"></p></form><small>Приглашение появится в локальном кабинете педагога.</small></div>${S.mentors.length?S.mentors.map(m=>`<div class="card"><h3 style="margin-bottom:20px">${m.status==='Подтверждён'?icon('check'):icon('clock')} ${esc(m.status)}</h3><div class="person-row">${photo(m.status==='Подтверждён'?'mentor':'teacher','Руководитель')}<div><h3>${esc(m.name)}</h3><p>Учитель · ${esc(m.email)}</p><small>МБОУ «Гимназия №1» (Демо)</small></div>${badge(m.status)}${m.status==='Ожидает подтверждения'?button('Отменить','cancel-invite','sm',`data-id="${m.id}"`):button(icon('mail')+' Написать','message','sm',`data-to="${m.teacher||''}"`)}</div></div>`).join(''):empty('Пригласи своего первого руководителя')}</div>`),
 security:()=>workspace('security','',heading('Безопасность аккаунта','Управляй доступом к своему аккаунту и настройками уведомлений.')+`<div class="spaced"><div class="card">${cardTitle('Email и доступ','','mail')}<div class="setting-row"><div><small>Email</small>　${esc(S.user.email)}　${badge('Подтверждён')}<p>На этот адрес приходят важные уведомления о конкурсе.</p></div>${button('ИЗМЕНИТЬ EMAIL','change-email','sm')}</div></div><div class="card"><div class="setting-row"><div><h3>${icon('lock')} Смена пароля</h3><p>Если ты подозреваешь, что кто-то знает твой пароль, измени его.</p></div>${button('ИЗМЕНИТЬ ПАРОЛЬ →','change-password','sm')}</div></div><div class="card">${cardTitle('Настройки уведомлений','','bell')}<p>Выбери, какие уведомления ты хочешь получать.</p>${[['Новости конкурса и важные объявления','Информация о новых этапах, сроках и возможностях'],['Статус проекта и комментарии жюри','Уведомления о проверке и обратной связи'],['Полезные материалы и события','Подборки, вебинары, новые статьи']].map(([t,p],i)=>`<div class="setting-row"><div>${icon('mail')}　${t}<p style="margin-left:30px">${p}</p></div><label class="switch"><input type="checkbox" data-setting="${i}" aria-label="${t}" ${S.user.profile.notifications?.[i]?'checked':''}><span></span></label></div>`).join('')}</div><div class="card"><div class="setting-row"><div><h3 style="color:#df454b">${icon('logout')} Выйти из аккаунта</h3><p>Ты можешь выйти из аккаунта на этом устройстве в любой момент.</p></div>${button('ВЫЙТИ','logout','danger sm')}</div></div></div>`),
 'test-intro':()=>publicPage('test-intro',banner('Проверь<br>свои знания<br>об Арктике','15 вопросов о природе, людях и будущем Севера.<br>У тебя будет ограниченное время. Будь внимателен!',{tall:true,landscape:false,crumb:false,eyebrow:'Всероссийский конкурс для школьников'})+`<div class="container"><form data-form="test-start"><div class="test-choices"><div><div class="feature">${icon('book','large')}<h3>Количество<br>вопросов</h3></div><p>Ты можешь выбрать<br>5, 10 или 15 вопросов.</p>${select('Количество','count',[5,10,15],15)}</div><div><div class="feature">${icon('clock','large')}<h3>Время на прохождение</h3></div><p>Отсчёт начнётся<br>сразу после начала теста.</p>${select('Время (минуты)','minutes',[10,15,20],20)}</div><div><div class="feature">${icon('file','large')}<h3>Темы вопросов</h3></div>${['Природа Арктики','Научные исследования','Люди Севера','Будущее Арктики'].map(t=>`<div class="mint-text" style="margin:10px 0">✓　<span class="muted">${t}</span></div>`).join('')}</div></div><p class="form-error" role="alert"></p><div class="field-actions"><button class="btn primary">${S.attempt&&!S.attempt.finished?'ПРОДОЛЖИТЬ ТЕСТ':'НАЧАТЬ ТЕСТ'} <span class="arrow-circle">→</span></button>${button(icon('settings')+' Советы по прохождению','test-tips','sm')}</div></form></div>`),
 test:()=>{const a=S.attempt;if(!a||a.finished)return publicPage('test',banner('Тест «Удивительная Арктика»','Проверь свои знания о Севере.')+`<div class="container">${empty(a?'Эта попытка завершена':'Сначала начни тест')}${link(a?'test-result':'test-intro',a?'Посмотреть результат →':'Начать тест →','btn primary')}</div>`);const i=a.index||0,q=a.bank[i];return publicPage('test',`<div class="hero-banner banner-landscape" style="min-height:130px"></div><div class="container"><div class="test-heading"><div>Тест «Удивительная Арктика»<h2 style="margin-top:8px">Вопрос ${i+1} из ${a.bank.length}</h2></div><div class="timer">${icon('clock')}<div><small>Осталось времени</small><strong style="display:block" data-timer>${Math.floor((a.deadline-Date.now())/60000)}:00</strong></div></div></div><div class="progress-bar"><span style="width:${(i+1)/a.bank.length*100}%"></span></div><form data-form="test-answer"><div class="question-layout">${photo('iceberg','Айсберг','question-photo')}<div><div class="eyebrow">${esc(q.topic)}</div><h2>${esc(q.q)}</h2>${q.a.map((t,j)=>`<label class="answer"><input type="radio" name="answer" value="${j}" ${a.answers[i]===j?'checked':''}>${esc(t)}</label>`).join('')}<p class="form-error" role="alert"></p></div></div><div class="test-bottom">${button('← Назад','test-back','sm',i===0?'disabled':'')}<button class="btn primary">${i===a.bank.length-1?'Завершить тест':'Следующий вопрос'} <span class="arrow-circle">→</span></button></div></form></div>`);},
 'test-result':()=>{const a=S.attempt;if(!a?.finished)return publicPage('test-result',banner('Результат теста','Заверши тест, чтобы узнать результат.')+`<div class="container">${empty('Результатов пока нет')}${link('test-intro','Пройти тест →','btn primary')}</div>`);const passed=a.percent>=a.pass;return publicPage('test-result',banner(passed?'Отличный<br>результат!':'Продолжай<br>исследовать!','Ты открываешь Арктику<br>и делаешь важный шаг к новым открытиям.',{landscape:false,crumb:false})+`<div class="container"><div class="result-grid"><div class="result-score"><div class="result-ring" style="--percent:${a.percent}%"><strong>${a.percent}%</strong></div><strong>${a.right} из ${a.bank.length}</strong><div>правильных ответов</div></div><div><div class="success-icon">${icon(passed?'check':'book','large')}</div><h3>${passed?'Тест пройден':'Есть что изучить'}</h3><p>${passed?'Ты показал(а) высокий уровень знаний об Арктике. Продолжай исследовать и узнавать больше о Севере!':'Изучи материалы в библиотеке и попробуй снова. Каждый вопрос — новое открытие.'}</p></div><div><h3>Результаты по темам</h3>${Object.entries(a.topics).map(([t,v])=>`<div class="topic-result"><span>${esc(t)}</span><div class="progress-bar"><span style="width:${v.right/v.total*100}%"></span></div><span>${Math.round(v.right/v.total*100)}%</span></div>`).join('')}</div></div><div class="field-actions">${passed?fileLink('certificate','СКАЧАТЬ СЕРТИФИКАТ (PDF)'):link('explore','ИЗУЧАТЬ АРКТИКУ →','btn')}${link('submit','ПЕРЕЙТИ К СОЗДАНИЮ ПРОЕКТА →','btn primary')}</div></div>`);},
 achievements:()=>{const a=S.attempt,has=a?.finished&&a.percent>=a.pass;return workspace('achievements','',heading('Мои достижения','Здесь хранятся твои сертификаты, дипломы и результаты участия.')+tabs(['Сертификаты','Дипломы','Все достижения'],0,'achievements')+(has?`<div class="certificate-layout"><div class="certificate">${brand()}<h2>СЕРТИФИКАТ</h2><div class="mint-text" style="letter-spacing:4px">УЧАСТНИКА</div><p>подтверждает, что</p><div class="certificate-name">${esc(name())}</div><p>успешно прошёл(ла) тест<br>«Удивительная Арктика»</p><h3>${a.right} из ${a.bank.length} (${a.percent}%)</h3><small>№ АРК-${a.id.slice(0,8).toUpperCase()}</small><a href="#/verify?id=${a.id}" aria-label="Проверить сертификат"><img class="certificate-qr" src="/api/qr?id=${a.id}" alt="QR-код проверки сертификата"></a></div><div><h3>Информация о сертификате</h3><dl class="data-list" style="margin:25px 0"><dt>Номер</dt><dd>АРК-${a.id.slice(0,8).toUpperCase()}</dd><dt>Дата выдачи</dt><dd>${date(a.finished)}</dd><dt>Статус</dt><dd>${badge('Действительный')}</dd><dt>Результат</dt><dd>${a.percent}%</dd></dl>${fileLink('certificate','СКАЧАТЬ СЕРТИФИКАТ (PDF)')}<div style="margin-top:15px">${button(icon('link')+' Поделиться','share','wide sm')}</div></div></div>`:empty('Достижений пока нет')));},
 submit:()=>{const p=currentProject();return publicPage('submit',banner('Подать<br>проект','Твои идеи могут открыть новые<br>горизонты Арктики. Поделись<br>исследованием, которое вдохновляет.',{tall:true,landscape:false,crumb:false,eyebrow:'Всероссийский конкурс для школьников'})+`<div class="container"><form data-form="project"><div class="columns"><div><h3 style="margin-bottom:18px">О проекте</h3><input type="hidden" name="id" value="${esc(p?.id||'')}">${field('Название проекта *','name',p?.name||'','text','maxlength="200" placeholder="Введите название проекта" data-counter="200"')}<small class="counter" data-counter-for="name"></small>${select('Номинация *','nomination',['Выберите номинацию','Экология','Биология','География','Технологии','Культура и люди','История','Астрономия'],p?.nomination)}${field('Краткая аннотация *','annotation',p?.annotation||'','textarea','maxlength="2000" data-counter="2000" placeholder="Расскажите о сути проекта, его актуальности и ожидаемых результатах"')}<small class="counter" data-counter-for="annotation"></small></div><div><h3>Файлы проекта</h3><p><small>Допустимые форматы и максимальный размер файлов настраиваются организатором конкурса.</small></p>${upload('Основной файл проекта (PDF/DOCX)','research',p,true)}${upload('Презентация (PDF/PPTX)','presentation',p)}${upload('Видео с защитой','video',p)}${field('Или ссылка на видео (HTTPS)','video',p?.video||'','url','placeholder="https://…"')}</div></div><p class="form-error" role="alert"></p><div class="field-actions"><button class="btn" name="mode" value="draft">${icon('file')} Сохранить черновик</button><button class="btn primary" name="mode" value="submit">Подать проект →</button></div></form></div>`);},
 project:()=>{const p=currentProject();return workspace('project','',heading('Мой проект','',link('submit',icon('edit')+' Редактировать проект','btn sm'))+(p?`<div class="project-hero"><div class="eyebrow">${esc(p.nomination)}</div><h2>${esc(p.name)}</h2><div class="field-actions"><small>Автор: ${esc(p.author)}</small><small>Подано: ${date(p.created)}</small></div></div>${steps(true)}<div class="notice" style="margin:12px 0 22px">${icon('clock')}Текущий статус: ${badge(p.status)}</div><div class="columns"><div class="card"><h3>Файлы проекта</h3>${fileCards(p)}</div><div class="card"><h3>Сообщения модерации</h3><div class="notice" style="background:#e9f5fb;margin:15px 0"><div><p>Ваш проект принят на проверку. Ожидайте результатов модерации.</p><p>${esc(p.reason||'В случае вопросов вы можете связаться с организатором через раздел сообщений.')}</p><small>${date(p.created)}</small></div></div>${button('Все сообщения →','messages','sm')}${button('Написать','message','sm',`data-project="${p.id}" data-to="admin"`)}</div></div>`:empty('Проект пока не создан')+link('submit','Подать проект →','btn primary')));},
 'project-results':()=>{const p=currentProject(),sent=p?.published;return workspace('project-results','',heading('Результаты проекта','Ниже представлены оценки экспертов и обратная связь.',sent?`<div class="card tinted"><h3>${icon('trophy')} Итоговый балл: ${((p.score||0)*10).toFixed(1)}</h3><small>Шкала 0–100</small></div>`:'')+(sent?`<div class="columns asymmetric"><div class="card"><h3>Оценки по критериям</h3><table class="score-table"><thead><tr><th>Критерий</th><th>Вес</th><th>Баллы (0–10)</th></tr></thead><tbody>${(S.config.criteria||criteria).map(([t,w],i)=>`<tr><td>${t}</td><td>${w}%</td><td>${p.reviews?.[0]?.scores?.[i]??'—'}</td></tr>`).join('')}<tr><td>Итоговый балл</td><td>100%</td><td>${(p.score||0).toFixed(2)}</td></tr></tbody></table></div><div class="card"><h3>Отзывы экспертов</h3>${p.reviews?.length?p.reviews.map((r,i)=>`<div class="expert-review"><strong>Эксперт ${i+1}</strong><p>${esc(r.comment||'Комментарий не добавлен')}</p><small>${date(r.date)}</small></div>`).join(''):empty('Отзывы не опубликованы')}</div></div><div class="card" style="margin-top:20px">${cardTitle('Итоговый документ',fileLink('diploma','Скачать'),'file')}<p>Диплом участника</p></div>`:empty('Результаты будут доступны после публикации комиссией')));},
 defense:()=>workspace('defense','',heading('ВКС-защита проекта','Подготовься к онлайн-защите. Ниже указаны время и технические требования.')+`<div class="columns"><div class="card">${cardTitle('Дата и время','','calendar')}<div class="defense-date">12 марта 2025<br>14:00 – 14:20</div><small>Демонстрационное расписание · встреча не назначена</small></div><div class="card">${cardTitle('Часовой пояс','','clock')}<strong>Москва (UTC+3)</strong><p>Убедись, что выставлен правильный часовой пояс в твоём календаре.</p></div></div><div class="card" style="margin-top:20px">${cardTitle('Ссылка на подключение','','link')}<div class="copy-row"><input class="control" value="Встреча не назначена" readonly aria-label="Ссылка на защиту">${button('Скопировать','copy-defense','sm')}</div></div><div class="columns" style="margin-top:20px"><div class="card">${cardTitle('Файл презентации для защиты','','file')}${fileCards(currentProject())}</div><div class="card">${cardTitle('Техническая подготовка','','settings')}${['Проверь стабильное интернет-соединение','Убедись в работе камеры и микрофона','Используй браузер последней версии','Подготовь краткую презентацию (до 10 минут)','Пройди тестовое подключение'].map((t,i)=>`<label class="checkbox"><input type="checkbox" ${i<3?'checked':''}>${t}</label>`).join('')}${button('Проверить сейчас →','meeting-check','sm')}</div></div>`)
};
